function rowSet(v){var i=POP.i,f=POP.f;if(f.indexOf('fm')===0){S.roles[i].fm=S.roles[i].fm||['人形','肉体','无','无','人'];S.roles[i].fm[parseInt(f.slice(2),10)]=v;closePop();renderAll();return;}if(f==='n')S.roles[i].n=parseInt(v,10);else if(f==='look')S.roles[i].look=v;else if(f==='sex')S.roles[i].sex=v;else if(f==='ageT')S.roles[i].ageT=v;else if(f==='cast')S.roles[i].cast=v;else S.roles[i].kind=v;closePop();renderAll();}
