function buildLines(fields){
var out=[],_lk=(S.look==='媒体')?'媒体':'影视';
(fields||[]).forEach(function(f){
 if(f.type==='grp'){if(f.look)out.push('项目基调='+_lk);return;}
 if(!f.type)return;
 if(!fieldOn(f))return;   /* 条件行未命中＝不出现也不回传 */
 if(f.lane==='film'&&_lk!=='影视')return;
 if(f.lane==='media'&&_lk!=='媒体')return;
 var _n=f.rt||f.label;
 if(f.type==='multi'){var _mv=(S.multi[f.k]||[]);var _ms=_mv.length?_mv.join('；'):'未选';
  if(f.k==='dur'&&_mv.length){var _pf=S.single.fcarrier?S.single.fcarrier+' ':'';_ms=_pf+_mv.join('；');}
  out.push(_n+'='+_ms);if(S.cst[f.k])out.push('自定义'+_n+'='+S.cst[f.k]);}
 else if(f.type==='tags'){var _tg=(S.multi[f.k]||[]);var _ts=_tg.length?_tg.join('；'):'未选';
  if(f.k==='dur'&&_tg.length){var _dp=S.single.fcarrier?S.single.fcarrier+' ':'';_ts=_dp+_tg.join('；');}
  out.push(_n+'='+_ts);}
 else if(f.type==='dualtags'){var _fx=(S.multi[f.k+'x']||[]);var _dv=(S.single[f.k]||'未选');
  out.push(_n+'='+_dv+' × '+(_fx.length?_fx.join(' + '):'未选'));}
 else if(f.type==='single'){var _sv=S.single[f.k]||'';if(!_sv&&f.opt)return;
  if(f.k==='dur'&&_sv){var _dp=S.single.fcarrier?S.single.fcarrier+' ':'';_sv=_dp+_sv;}
  out.push(_n+'='+(_sv||'未选'));if(S.cst[f.k])out.push('自定义'+_n+'='+S.cst[f.k]);}
 else if(f.type==='text'){var _tv=S.text[f.k];out.push(_n+'='+(_tv||'（未填）'));}
else if(f.type==='roles'){
var _pr=S.pr,_fmx=function(a){var o=(a||['人形','肉体','无','无','人']).slice(0,5);while(o.length<5)o.push('无');return o.join(' × ');};
if(_pr.mode==='创建角色'){
out.push(f.label+'=创建角色（'+(_pr.count||1)+' 个）');
(S.roles||[]).forEach(function(r,ix){var _p=r.vp||{};
out.push('新角色 '+(ix+1)+'｜性别='+(r.sex||'女')+'｜形象='+_fmx(r.fm)+'｜年龄='+(r.ageT||'25-30')+'｜出演='+(r.cast||'主演')
+'｜简介='+(r.intro||'（待填）')+'｜提供设定图='+(r.img?'是':'否')+'｜提供声纹='+(_p.on?'是':'否'));});
}
if(_pr.edit){
var _ns=Object.keys(_pr.edits||{});
out.push(f.label+'=修改角色（'+(_ns.length?_ns.join('／'):'未选')+'）');
_ns.forEach(function(nm){var m=(_pr.meta&&_pr.meta[nm])||{},e=_pr.edits[nm]||{};
out.push(nm+'｜性别='+(m.g||'女')+'｜形象='+_fmx(m.mf)+'｜年龄='+(m.age||'25-30')+'｜出演='+(m.c||'主演')
+'｜简介='+(m.intro||'（待填）')+'｜更新设定图='+(e.regen?'是':'否')+'｜更新声纹='+(e.vp?'是':'否'));});
}
if(_pr.mode==='无需创角')out.push(f.label+'=无需创角');
else if(!_pr.mode&&!_pr.edit)out.push(f.label+'=未选择');}
});
return out;}
